import{_ as s,o as a,c as r,ag as t}from"./chunks/framework.DPTJCqgd.js";const o="/deepseek-harness-desktop/assets/harness-desktop-main.DPzz4bzZ.png",d="/deepseek-harness-desktop/assets/harness-desktop-models.DzzrXzFw.png",m=JSON.parse('{"title":"Harness Desktop","description":"基于 DeepSeek Harness 的社区桌面应用。配置自己的模型，在本地项目中工作，并通过插件扩展功能。","frontmatter":{"editSource":"docs/user/index.zh.md","editSourceUrl":"https://github.com/Bestbbb/deepseek-harness-desktop/edit/2847c75ea844b05f9d8adca865940856f1286c8c/docs/user/index.zh.md","layout":"page","title":"Harness Desktop","description":"基于 DeepSeek Harness 的社区桌面应用。配置自己的模型，在本地项目中工作，并通过插件扩展功能。"},"headers":[],"relativePath":"index.md","filePath":"index.md"}'),i={name:"index.md"};function n(p,e,h,l,c,b){return a(),r("div",null,[...e[0]||(e[0]=[t('<main class="dsh-home"><section class="dsh-hero"><div class="dsh-hero-copy"><h1 id="在桌面上使用-deepseek-harness。" tabindex="-1">在桌面上使用 DeepSeek Harness。 <a class="header-anchor" href="#在桌面上使用-deepseek-harness。" aria-label="Permalink to &quot;在桌面上使用 DeepSeek Harness。&quot;">​</a></h1><p>在本地项目中使用自己选择的模型，通过插件组合 agent（智能体）的能力。</p><div class="dsh-actions"><p><a href="https://github.com/Bestbbb/deepseek-harness-desktop/releases" target="_blank" rel="noreferrer">下载</a> <a href="./guide/quickstart">阅读指南</a></p></div></div><div class="dsh-hero-preview"><p><img src="'+o+'" alt="配置模型前的 Harness Desktop 会话工作区"></p></div></section><section class="dsh-models"><div class="dsh-models-copy"><h2 id="选择适合你的模型。" tabindex="-1">选择适合你的模型。 <a class="header-anchor" href="#选择适合你的模型。" aria-label="Permalink to &quot;选择适合你的模型。&quot;">​</a></h2><p>配置 DeepSeek、其他受支持的提供方，或兼容 OpenAI 的网关。推理和计费由模型提供方负责。</p><p><a href="./guide/providers">模型配置与认证</a></p></div><div class="dsh-models-preview"><p><img src="'+d+'" alt="包含提供方配置控件的 Harness Desktop 模型设置"></p></div></section><section class="dsh-extension"><h2 id="可按需扩展的桌面应用。" tabindex="-1">可按需扩展的桌面应用。 <a class="header-anchor" href="#可按需扩展的桌面应用。" aria-label="Permalink to &quot;可按需扩展的桌面应用。&quot;">​</a></h2><p>Harness 负责 agent 运行时，Tauri 提供原生窗口和操作系统集成。</p><div class="dsh-extension-grid"><div><h3 id="需要原生能力的地方-使用原生实现" tabindex="-1">需要原生能力的地方，使用原生实现 <a class="header-anchor" href="#需要原生能力的地方-使用原生实现" aria-label="Permalink to &quot;需要原生能力的地方，使用原生实现&quot;">​</a></h3><p>系统 WebView、原生菜单、快捷键、运行时监管和诊断导出。不内置 Electron 或 Chromium。</p><p><a href="https://github.com/Bestbbb/deepseek-harness-desktop/blob/2847c75ea844b05f9d8adca865940856f1286c8c/apps/desktop/README.zh.md" target="_blank" rel="noreferrer">桌面架构</a></p></div><div><h3 id="以插件组合功能" tabindex="-1">以插件组合功能 <a class="header-anchor" href="#以插件组合功能" aria-label="Permalink to &quot;以插件组合功能&quot;">​</a></h3><p>使用 Cordis 插件、Agent 预设、skill（技能）和 MCP（Model Context Protocol）集成。可选的 Codex 和 Claude Code 组合包经配置后提供任务委派能力。</p><p><a href="./develop/basic/">插件开发</a></p></div></div></section><section class="dsh-start"><h2 id="从一个本地项目开始。" tabindex="-1">从一个本地项目开始。 <a class="header-anchor" href="#从一个本地项目开始。" aria-label="Permalink to &quot;从一个本地项目开始。&quot;">​</a></h2><ol><li><strong>安装。</strong> 在发布附件中选择 macOS Apple Silicon 或 Windows x64 安装包。</li><li><strong>连接。</strong> 在设置中配置模型提供方，使用它支持的认证方式。</li><li><strong>开始工作。</strong> 选择工作区和 Agent 预设，然后描述任务。</li></ol><div class="dsh-preview-note"><h3 id="安装前请了解" tabindex="-1">安装前请了解 <a class="header-anchor" href="#安装前请了解" aria-label="Permalink to &quot;安装前请了解&quot;">​</a></h3><p>这是社区预览版，并非 DeepSeek 官方产品。macOS 预览版采用 ad-hoc 签名且未经公证；Windows 预览版未签名。请查看每个版本的平台说明及内置版本。</p><p>本地执行不等于离线推理。插件和外部 agent 会执行代码，请在授权工作区访问前检查权限。自动更新尚未配置。</p><p><a href="https://github.com/Bestbbb/deepseek-harness-desktop/releases" target="_blank" rel="noreferrer">下载</a></p></div></section><footer class="dsh-home-footer"><p><a href="https://github.com/Bestbbb/deepseek-harness-desktop" target="_blank" rel="noreferrer">GitHub 源码</a></p><p><a href="https://github.com/deepseek-ai/deepseek-harness" target="_blank" rel="noreferrer">上游 Harness</a></p><p><a href="https://github.com/Bestbbb/deepseek-harness-desktop/blob/2847c75ea844b05f9d8adca865940856f1286c8c/LICENSE" target="_blank" rel="noreferrer">MIT 许可证</a></p></footer></main>',1)])])}const f=s(i,[["render",n]]);export{m as __pageData,f as default};
